// The real-run numbers the /data page and the docs charts draw. The JSON is generated by
// scripts/make_site_data.py from datasets/probate-real-run (never edited by hand) and a Python test checks it
// against the verifier's claims.
import raw from './generated/family-data.json';

export type Gen = {
  gen: number;
  name: string;
  branch: string;
  rules: 'v1' | 'v2';
  state: 'tried' | 'died_early';
  born: string;
  died: string | null;
  lifeSeconds: number | null;
  met: number;
  resisted: number;
  falseBlocks: number;
  instinctsAtBirth: number;
  newInstinct: boolean;
  cause: string | null;
  gateWorking: boolean;
  judgeOutages: number;
};

export type Branch = {
  branch: string;
  whatDiffers: string;
  firstGen: number;
  lastGen: number;
  learning: boolean | null;
  codeCommit: string;
  generationsTried: number;
  diedEarly: number;
  resisted: number;
  met: number;
  rate: number;
  wilson95: [number, number] | null;
  perGeneration: Record<string, [number, number]>;
  instinctsAtStart: number;
  instinctsAtEnd: number;
  instinctsLearned: number;
  falseBlocks: number;
  judgeOutages: Record<string, number>;
};

export type Instinct = { name: string; learnedFrom: number; firstCarriedBy: number };

export const data = raw as unknown as {
  dataset: { name: string; exportedAt: string; hf: string; publishedRelease: string; pendingRelease: string; claimsChecked: number };
  totals: { generations: number; tried: number; instincts: number };
  wilsonNote: string;
  generations: Gen[];
  instincts: Instinct[];
  branches: Branch[];
  v1: {
    generations: string;
    generationsTried: number;
    workingGateFrom: number;
    resistedWorkingGate: number;
    metWorkingGate: number;
    wilson95WorkingGate: [number, number];
    attacksResistedWithoutWorkingGate: number;
    generationsWithoutWorkingGate: number;
  };
  judgeOutageGenerations: number[];
  falseBlockGenerations: number[];
  neverBornGenerations: number[];
};

/** Every family line, in the order the charts and filters list them. */
export const LINES = ['v1', 'v2-first-generation', 'v2-h-inherit', 'v2-h-control', 'v2-h-fresh', 'v2-main'] as const;
export type Line = (typeof LINES)[number];

export const LINE_LABEL: Record<string, string> = {
  v1: 'v1 real run',
  'v2-first-generation': 'v2 first generation',
  'v2-h-inherit': 'v2-h-inherit',
  'v2-h-control': 'v2-h-control',
  'v2-h-fresh': 'v2-h-fresh',
  'v2-main': 'v2-main',
};

/** One colour per line, from the site tokens (set in global.css). Every chart also labels lines directly. */
export const LINE_COLOR: Record<string, string> = {
  v1: 'var(--line-v1)',
  'v2-first-generation': 'var(--line-v1)',
  'v2-h-inherit': 'var(--line-inherit)',
  'v2-h-control': 'var(--line-control)',
  'v2-h-fresh': 'var(--line-fresh)',
  'v2-main': 'var(--line-main)',
};

export const pct = (n: number) => `${Math.round(n * 100)}%`;

export function branchByName(name: string): Branch {
  const b = data.branches.find((x) => x.branch === name);
  if (!b) throw new Error(`unknown branch ${name}`);
  return b;
}

/** "27 Nov 2026, 20:22 to 20:27 UTC", or just the day when the life never started. */
export function lifeDates(g: Gen): string {
  const d = new Date(g.born);
  const day = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
  const hm = (iso: string) =>
    new Date(iso).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' });
  if (g.state === 'died_early' || !g.died) return `${day} (never born)`;
  return `${day}, ${hm(g.born)} to ${hm(g.died)} UTC`;
}

/** What happened to the generation, in a few words (from the rows, no text of ours). */
export function outcome(g: Gen): string {
  if (g.state === 'died_early') return 'Never born (Fly refused to create its Sprite)';
  if (g.met === 0) return 'Met no attacks';
  return `Resisted ${g.resisted} of ${g.met} attacks`;
}
